from cloud_common import *  # noqa: F401,F403
R = 'f7-cloud'
T = []

# ---------------------------------------------------------------- 687 fast, reliable CI
T.append(topic(687, 'fast-reliable-ci', R, 26, 'Fast, Reliable CI: Caching, Parallelism and Flaky Tests',
 ['Explain why CI speed and trust decide whether people integrate often',
  'Speed up a pipeline with caching, sharding and running only what a change affects',
  'Find, quarantine and fix flaky tests before they teach everyone to click retry'],
 2, 12, [323],
 [text(687, 1, 'Speed and trust are the product',
   'Continuous integration only works if people run it on every small change and believe its answer. A pipeline that takes an hour gets batched changes and context switches; one that fails at random gets retried until green, so real failures slip through. Two numbers describe CI health: how long a typical run takes from push to result, and how often a failure is real. Aim for minutes, not hours, and for red to mean broken.',
   ['ci-feedback']),
  text(687, 2, 'Caching: do not redo work that has not changed',
   'Most CI time goes on repeating identical work: downloading dependencies, rebuilding unchanged modules and image layers. A cache stores the output under a key built from the inputs, such as a hash of the dependency lock file. Same inputs, same key, so the step is skipped. The key must include every input that matters, or a stale cache produces builds that pass in CI and fail elsewhere. Order image build steps so rarely changing layers come first.',
   ['build-caching']),
  text(687, 3, 'Worked example: sharding a slow suite',
   'A test suite takes 40 minutes on one runner. Split into 8 shards that run at the same time, each does about 40 ÷ 8 = 5 minutes of tests plus 2 minutes of setup, so the run finishes in about 7 minutes. Total machine time rises from 42 to 8 × 7 = 56 machine-minutes, a cost for a much faster answer. Balance shards by recorded test durations, not test counts, or one slow shard sets the pace.',
   ['test-parallelism']),
  diagram(687, 4, 'Handling a flaky test', 'A flaky test is a bug to fix, not a reason to retry.', ['flaky-tests'],
   ['A test fails, then passes on rerun with no code change',
    'CI records it as flaky in a test history',
    'It moves to a quarantine suite that runs but does not block merges',
    'A ticket goes to the owning team with the failure logs',
    'The cause is fixed: timing, ordering, shared state or an external call',
    'The test returns to the blocking suite, or is deleted']),
  text(687, 5, 'Trap: automatic retries on every failure',
   'Retrying every failed test three times makes the pipeline green again, and hides two problems. Real intermittent bugs, such as race conditions, now pass if they fail only some of the time, and flaky tests pile up because nothing forces a fix. If you retry, record every pass-after-retry as flaky, report it, and cap how long a test may stay in quarantine.',
   ['flaky-tests'])],
 [mc('t687-a1', 'ci-feedback', 'Developers start batching a week of work into each merge. Which CI problem most likely caused it?',
   [('a', 'Runs take about an hour and often fail for no clear reason'),
    ('b', 'The pipeline runs on each push rather than nightly'),
    ('c', 'Branch protection requires a passing build to merge'),
    ('d', 'Each run posts a full test report as a comment on the pull request')], 'a',
   'Slow, untrusted runs make each merge expensive, so people merge less often. Running on every push is what CI should do, requiring green builds is normal protection, and posting a report only changes where results appear.'),
  mc('t687-a2', 'build-caching', 'A dependency cache is keyed only on the operating system. What goes wrong?',
   [('a', 'The cache misses on each run, so all dependencies download again'),
    ('b', 'A lock-file change can reuse old dependencies from the cache'),
    ('c', 'The cache grows without limit and fills the runner disk'),
    ('d', 'Parallel jobs cannot read the cache at the same time')], 'b',
   'The key must include the inputs, such as a hash of the lock file; without it, a new dependency version can be skipped and the build tests the wrong code. A missing key part causes stale hits, not misses, cache storage is bounded by the CI system, and parallel reads are normal.'),
  mc('t687-a3', 'flaky-tests', 'A test fails about once in 50 runs on unchanged code. What should the team do first?',
   [('a', 'Delete it, because a test that fails at random has no value'),
    ('b', 'Add three automatic retries so it stops blocking merges'),
    ('c', 'Quarantine it as non-blocking, and ticket its owner to fix it'),
    ('d', 'Raise the timeouts across the suite so that it passes more reliably')], 'c',
   'Quarantine stops it blocking merges while keeping it running and visible, and an owner fixes the cause. Deleting it loses coverage that may catch a real race, silent retries hide the flake, and raising timeouts across the suite slows the suite without fixing whatever is non-deterministic.'),
  mc('t687-a4', 'test-parallelism', 'A suite is split into 8 shards by test count, but one shard always finishes last by 10 minutes. Why?',
   [('a', 'Shards are balanced by count, so one holds the slowest tests'),
    ('b', 'Runners are slower when more than four run at the same time'),
    ('c', 'The last shard waits for the others to free the cache'),
    ('d', 'Tests inside each shard run in a different random order on each run')], 'a',
   'Equal counts are not equal durations; balance shards by recorded timings. Running several runners does not by itself slow each one, caches are read in parallel, and order within a shard does not change its total time.'),
  est('t687-a5', 'test-parallelism', 'A 48-minute test suite is split into 6 shards balanced by recorded durations, and each shard spends 3 minutes on setup. About how many minutes until every shard has finished?', 'minutes', 11,
   ['Shards run at the same time on separate runners', 'Balancing by duration makes each shard about equal'], '48 ÷ 6 + 3', '8 minutes of tests + 3 minutes of setup = 11 minutes',
   'Sanity check: machine time rises from 51 to 6 × 11 = 66 runner-minutes, so you pay for a roughly 4.6 times faster answer, and once setup dominates each shard, more shards stop helping.', 0.1, [8, 51]),
  order('t687-a6', 'ci-feedback', 'Order the stages of a pipeline that gives the fastest useful feedback.',
   ['Restore caches keyed on the inputs', 'Lint and compile', 'Run unit tests in parallel shards', 'Build the artefact once', 'Run slower integration tests against it'],
   ['s3', 's1', 's5', 's2', 's4'], 'Cheap checks that fail most often run first, so most broken changes fail within minutes; slower tests run against the one artefact that will ship.')],
 flash(687, [('Two numbers for CI health?', 'Time from push to result, and how often a failure is real.'),
             ('A good cache key?', 'A hash of every input that affects the output, such as the lock file.'),
             ('Flaky test policy?', 'Record, quarantine as non-blocking, ticket the owner, fix or delete within a time limit.')]),
 src([('Martin Fowler: Continuous Integration', 'https://martinfowler.com/articles/continuousIntegration.html'),
      ('Martin Fowler: Eradicating Non-Determinism in Tests', 'https://martinfowler.com/articles/nonDeterminism.html'),
      ('Docker Docs: Optimize cache usage in builds', 'https://docs.docker.com/build/cache/optimize/')]),
 deep(['ci-feedback', 'build-caching', 'test-parallelism', 'flaky-tests'], 'How fast, trustworthy CI is built',
  ['A CI run is valuable only if it arrives quickly and tells the truth. Slow feedback pushes people to batch work and switch tasks while they wait, which makes merges larger and failures harder to trace. False failures teach people to retry until green, and once that habit forms, real failures are retried away too. Track the typical and slowest run times, the share of failures that were real, and how often runs are retried.',
   'Caching removes repeated work. Dependency caches are keyed on a hash of the lock file and the platform, so they are reused until the dependencies change. Build caches store compiled outputs by a hash of their inputs, so only changed modules rebuild. Image builds reuse layers when earlier steps are unchanged, so dependency installation goes before copying source code. A wrong key causes stale results, which is worse than a slow build.',
   'Parallelism cuts wall-clock time. Independent stages run at the same time, and large test suites split into shards across runners. Shards should be balanced using recorded durations, and each shard pays the setup cost, so there is a point where more shards add machine time without saving much. Running only the tests affected by a change, using the build’s dependency graph, helps large repositories, with a full run on a schedule as a safety net.',
   'Ordering matters. Fast, likely-to-fail checks such as formatting, linting, compiling and unit tests run first, so most broken changes fail in minutes. The artefact is built once and the slower integration and end-to-end tests run against it, which keeps what was tested identical to what ships. Expensive suites can run after merge or nightly, as long as failures there are owned and fixed quickly.',
   'Flaky tests are bugs in tests or code. Common causes are timing assumptions, order dependence, shared state between tests, and calls to real external services. CI should record which tests pass only on retry, move them to a non-blocking quarantine with an owner, and limit how long they stay there. Fixing the cause, by controlling time, isolating state or replacing external calls with fakes, is what restores trust.'],
  ['Teams that merge many small changes a day and need answers in minutes.', 'Large suites where caching and sharding turn hours into minutes.'],
  ['Avoid blanket automatic retries that hide flaky tests and real races.', 'Avoid cache keys that leave out inputs, which produce stale builds.'],
  ['Technique', 'Saves', 'Risk if done badly'],
  [['Dependency and build caching', 'Repeated downloads and rebuilds', 'Stale results from a bad key'],
   ['Sharding tests', 'Wall-clock time', 'Unbalanced shards, more machine time'],
   ['Running only affected tests', 'Work on large repositories', 'Missed tests if the graph is wrong']],
  'A pipeline before and after',
  ['Dependency install takes 4 minutes, 30 s with a warm cache', 'A 40-minute serial test suite, 8 shards with 2 minutes of setup each', 'About 5 minutes of lint, compile and build, illustrative'],
  ['Before: 4 + 40 + 5 = 49 minutes per run.',
   'Tests in shards: 40 ÷ 8 = 5 minutes, plus 2 minutes setup, so about 7 minutes.',
   'After: about 0.5 + 7 + 5 = 12.5 minutes, roughly four times faster.'],
  'Caching and sharding cut an illustrative 49-minute run to about 13 minutes, which is the difference between waiting and batching.',
  'Non-determinism in tests', 'Publicly reported',
  'Martin Fowler’s article on eradicating non-determinism in tests describes how flaky tests destroy trust in a suite, recommends quarantining them so they do not block the build, and warns that quarantined tests must be fixed quickly. His continuous integration article argues that a fast build, around ten minutes, is part of what makes integrating often practical, and Docker’s documentation explains ordering build steps so cached layers are reused.',
  [('“The build is red again, just rerun it.”', '“I’d check whether that test is flaky, quarantine it with an owner, and fix the cause.”'),
   ('“CI takes an hour, so I’ll merge once at the end of the week.”', '“I’d cache dependencies and shard the tests so each small change gets an answer in minutes.”')],
  ['CI must be fast and trustworthy, or people batch work and ignore red.', 'Cache by a hash of the inputs; a wrong key gives stale builds.', 'Shard by recorded durations and run cheap checks first.', 'Quarantine flaky tests with an owner and a time limit; fix the cause.']),
 predict('Retries for everything',
  'To stop random failures, a team configures every test to retry up to 3 times. Months later a race condition is introduced that makes one test fail about 30% of the time.',
  [('a', 'The race reaches production, because a retry usually passes',
    'Right: with three retries, a 30% failure passes almost every time, so the bug ships.'),
   ('b', 'The test fails every run, so the race is caught at once',
    'A 30% failure is intermittent; retries turn most of those failures into passes.'),
   ('c', 'CI marks the change as flaky and blocks the merge for review',
    'Only if it records passes-after-retry; plain retries just report green.')], 'a',
  'Record every pass-after-retry as flaky, report it, and treat a newly flaky test after a change as a likely real bug.'),
 see([(323, 'The pipeline stages and build-once rule this lesson speeds up'), (321, 'Image layers and why their order decides cache reuse'), (324, 'Progressive delivery that relies on trustworthy test results')])))

# ---------------------------------------------------------------- 690 alerting and on-call health
T.append(topic(690, 'alerting-on-call-health', R, 27, 'Alerting and Healthy On-Call',
 ['Write alerts on user-facing symptoms that a person must act on now',
  'Route each signal to a page, a ticket or a dashboard by urgency',
  'Keep on-call load sustainable with alert reviews, rotations and handoffs'],
 2, 12, [326, 327],
 [text(690, 1, 'Every page should need a human, now',
   'A page interrupts sleep and focus, so it must be urgent, actionable and about something users feel. Alert on symptoms such as errors, latency and failed jobs, measured against the SLO, rather than on causes such as high CPU on one host, which may or may not matter. Causes belong on dashboards to help diagnose a symptom once it pages. If the right response to an alert is to wait and see, it should not page.',
   ['symptom-alerts']),
  text(690, 2, 'Page, ticket or dashboard',
   'Urgency decides where a signal goes. A page is for user impact now or within the hour. A ticket is for problems that need a person within days, such as a disk that will fill in two weeks or a certificate that expires next month. A dashboard or log is for information that helps diagnose but needs no action. Many noisy setups page on what should be tickets, and train people to ignore pages.',
   ['page-vs-ticket']),
  diagram(690, 3, 'Reviewing an alert', 'Each page earns its place or is changed.', ['alert-hygiene'],
   ['A page fires and on-call responds', 'The response is logged: real impact, action taken, or no action', 'A weekly review looks at every page from the rotation', 'Pages with no action are removed, retuned or downgraded to tickets', 'Repeated causes get a fix or automation', 'Alert count and pages per shift are tracked over time']),
  text(690, 4, 'Worked example: sizing a rotation',
   'Google’s SRE book caps on-call at 25% of an engineer’s time. A rotation that always has a primary and a secondary, in week-long shifts, has 2 people on call at any moment. To keep each person at 25%, you need 2 ÷ 0.25 = 8 engineers, so each one is on call one week in four. A team of 4 can cover the same rota only at 50% each, which leaves little time to fix what pages them.',
   ['oncall-load']),
  text(690, 5, 'Trap: adding an alert after every incident',
   'After each incident someone adds an alert for its exact cause. A year later there are hundreds, most for causes that never recur, many firing together for one problem. Prefer one symptom alert that would have caught the incident, group related alerts into one notification, and delete alerts that have not led to action in months. The SRE book suggests no more than about two incidents per 12-hour shift, so there is time to handle each one properly.',
   ['alert-hygiene', 'oncall-load'])],
 [mc('t690-a1', 'symptom-alerts', 'Which alert is best suited to paging someone at 3 a.m.?',
   [('a', 'CPU on one web server has been above 90% for 10 minutes'),
    ('b', 'A database replica is two seconds behind its primary'),
    ('c', 'Checkout errors are burning the monthly budget fast'),
    ('d', 'Disk use on the log volume reached 75% today')], 'c',
   'Checkout errors are a user-facing symptom tied to the SLO, so someone must act. High CPU on one host may cause no user impact, two seconds of replica lag is often within normal bounds, and a disk at 75% is a ticket for working hours.'),
  mc('t690-a2', 'page-vs-ticket', 'A TLS certificate expires in 21 days and renewal is manual. How should this be signalled?',
   [('a', 'A page now, so nobody can forget about it'),
    ('b', 'A ticket to the owning team, paging only if it is days away'),
    ('c', 'A dashboard panel showing the days left until the certificate expires'),
    ('d', 'No signal, since renewal will happen before it expires')], 'b',
   'Three weeks out it needs a person within days, which is a ticket, with a page as a last-resort backstop. A page now interrupts someone for something that can wait, a dashboard needs someone to look, and assuming renewal will happen is how certificates expire.'),
  mc('t690-a3', 'alert-hygiene', 'A review shows most pages last month needed no action. What should change?',
   [('a', 'Retune, downgrade to tickets or delete those alerts'),
    ('b', 'Add a second on-call person to share the extra pages'),
    ('c', 'Raise the paging threshold on all of the alerts by 20%'),
    ('d', 'Mute the alerting system outside business hours')], 'a',
   'Each non-actionable page should be fixed individually, which is what the review is for. A second person shares the noise rather than removing it, a blanket threshold change also delays real alerts, and muting at night stops all pages, including real ones.'),
  mc('t690-a4', 'oncall-load', 'A database failure triggers 120 alerts in two minutes, all paging the same engineer. What helps most?',
   [('a', 'Raising the paging rate limit so none of them are dropped'),
    ('b', 'Paging a different engineer for each group of alerts'),
    ('c', 'Turning those alerts off until the database is stable'),
    ('d', 'Grouping related alerts so the incident sends one page')], 'd',
   'Grouping and dependency-aware suppression turn one cause into one page with the details attached. More pages, or more engineers paged, add noise to the same incident, and turning alerts off removes the signal you need to see it recover.'),
  est('t690-a5', 'oncall-load', 'A rotation always has a primary and a secondary on call, in week-long shifts. With on-call capped at 25% of each person’s time, how many engineers does the rotation need?', 'engineers', 8,
   ['Both roles count as on-call time', 'Shifts are shared evenly'], '2 people on call ÷ 0.25', '2 ÷ 0.25 = 8 engineers',
   'Sanity check: with 8, each person is on call one week in four, which matches the 25% cap; forgetting the secondary gives 4, which doubles everyone’s load.', 0.05, [4, 2]),
  tradeoff('t690-a6', 'page-vs-ticket', 'A batch export that users read each morning sometimes fails overnight; a rerun takes 20 minutes.',
   ['Users read the export from 8 a.m.', 'Failures happen about twice a month', 'The team wants fewer night pages'],
   [('p1', 'Page on-call the moment any export run fails', 'Page at once'),
    ('p2', 'Retry it automatically, and page only if it is still failing close to its deadline', 'Auto-retry, page near deadline'),
    ('p3', 'Open a ticket for the morning and let users wait', 'Ticket only')], 'p2',
   [('r1', 'An automatic retry fixes many transient failures with no human'), ('r3', 'Paging at once is needed because every failure is urgent'),
    ('r2', 'Paging near the deadline still protects the 8 a.m. readers'), ('r4', 'A ticket is enough because users can wait for the export')],
   ['r1', 'r2'], ['r3', 'r4'],
   {'r3': 'A failure at 1 a.m. with a 20-minute rerun is not urgent until the deadline is close.',
    'r4': 'Users rely on it at 8 a.m., so a morning ticket means they start the day without it.'},
   'Page on the user-facing deadline, not on the first failure: automate the retry and wake someone only when the symptom is about to reach users.')],
 flash(690, [('What should page?', 'Urgent, actionable, user-facing symptoms, usually tied to the SLO.'),
             ('Page vs ticket?', 'Page for impact now; ticket for things that need a person within days.'),
             ('A healthy on-call load?', 'At most about 25% of time on call and about two incidents per 12-hour shift.')]),
 src([('Google SRE book: Monitoring Distributed Systems', 'https://sre.google/sre-book/monitoring-distributed-systems/'),
      ('Google SRE book: Being On-Call', 'https://sre.google/sre-book/being-on-call/'),
      ('Google SRE workbook: On-Call', 'https://sre.google/workbook/on-call/'),
      ('Google SRE workbook: Alerting on SLOs', 'https://sre.google/workbook/alerting-on-slos/')]),
 deep(['symptom-alerts', 'page-vs-ticket', 'alert-hygiene', 'oncall-load'], 'How alerting and on-call stay sustainable',
  ['Good alerting starts from what users experience. Symptom alerts fire when a user-facing signal, such as error rate, latency, freshness or throughput, threatens the SLO. Cause-based signals, such as CPU, memory, queue depth or replica lag, are kept for diagnosis on dashboards, because the same cause can be harmless one day and critical the next. Alerts on the SLO with burn-rate windows give pages that are both early and rare.',
   'Each signal gets a destination by urgency. Pages are for impact now or imminent. Tickets go to a queue that the team works through in normal hours, for slow trends and upcoming expiries. Dashboards and logs hold everything else. The same condition can have both: a ticket when a disk will be full in two weeks, and a page if it will be full in two hours.',
   'Alerts decay unless they are reviewed. Each page is logged with what was done; a regular review removes or changes pages that needed no action, merges duplicates, and turns repeated manual fixes into automation. Grouping and inhibition send one notification per incident rather than one per failing component. Every alert has an owner and a linked runbook that says what to check first.',
   'On-call load is a capacity question. Google’s SRE book suggests no more than 25% of an engineer’s time on call, and no more than about two incidents per 12-hour shift, so each one can be handled, followed up and written up. With a primary and a secondary, that means about 8 people for a single-site rotation of week-long shifts, or two sites splitting the day so nobody is paged at night.',
   'People need support as well as tools. Clear escalation paths, a secondary who can take over, handoff notes at the end of each shift, compensation or time off after a hard night, and blameless postmortems keep on-call humane. Tracking pages per shift, night-time pages and time to acknowledge shows whether load is going up, and is the evidence for fixing noisy alerts or adding people.'],
  ['Services with an SLO and a rotation that should be paged only for real user impact.', 'Teams whose on-call has become noisy and needs a review process.'],
  ['Avoid paging on causes such as CPU or memory that may not affect users.', 'Avoid adding a new page for the exact cause of every past incident.'],
  ['Destination', 'Use for', 'Response time'],
  [['Page', 'User impact now or within the hour', 'Minutes'],
   ['Ticket', 'Slow trends, expiries, follow-ups', 'Days'],
   ['Dashboard or log', 'Diagnosis and context', 'When someone looks']],
  'Cutting pages after a review',
  ['A rotation gets 30 pages a week', 'The review finds 18 needed no action', 'Week-long shifts with one primary, illustrative'],
  ['Actionable pages: 30 − 18 = 12 a week.',
   'Per day: 12 ÷ 7 ≈ 1.7 pages, against roughly 4.3 before.',
   'Fixing the 18 removes 60% of interruptions without losing a real signal.'],
  'One review that removes non-actionable pages cuts an illustrative rotation’s load by more than half and brings it under two pages a day.',
  'On-call guidance from Google’s SRE books', 'Publicly reported',
  'Google’s SRE book recommends alerting on symptoms rather than causes and keeping pages actionable. Its Being On-Call chapter describes keeping on-call to at most 25% of SRE time, a maximum of about two incidents per 12-hour shift, and a minimum of eight engineers for a single-site rotation with a primary and secondary on week-long shifts. The SRE workbook adds practical guidance on reducing pager load.',
  [('“Let’s page on CPU over 90% so we catch problems early.”', '“I’d page on the user-facing symptom and keep CPU on the dashboard for diagnosis.”'),
   ('“We had an outage, so let’s add an alert for that exact cause.”', '“I’d check whether a symptom alert would have caught it, and only add one if not.”')],
  ['Page only for urgent, actionable, user-facing symptoms.', 'Route by urgency: page now, ticket within days, dashboard for context.', 'Review every page; remove, retune or downgrade the ones with no action.', 'Cap on-call near 25% of time and about two incidents per shift.']),
 predict('The alert for everything',
  'A service has 400 alerts, most added after past incidents. On-call gets about 50 pages a week, and engineers have started to acknowledge pages without looking.',
  [('a', 'A real outage is acknowledged and missed among the noise',
    'Right: alert fatigue makes every page look like the usual noise, including the real one.'),
   ('b', 'Coverage is complete, so the next outage is caught at once',
    'More alerts do not help if nobody reads them; coverage on paper is not attention.'),
   ('c', 'The paging system starts dropping pages above its rate limit',
    'Paging tools handle this volume; the failure is human attention, not the system.')], 'a',
  'Cut pages to actionable symptoms, review them weekly, and track pages per shift so the noise cannot creep back.'),
 see([(326, 'SLOs and burn rates that symptom alerts are built on'), (327, 'Incident response that starts when a page fires'), (689, 'Turning repeated alert fixes into automation and runbooks')])))

# ---------------------------------------------------------------- 689 toil and automation
T.append(topic(689, 'toil-runbooks-automation', R, 28, 'Toil, Runbooks and Automation',
 ['Recognise toil and measure how much of a team’s time it takes',
  'Decide which manual tasks to automate first, using frequency and payback',
  'Move a task from runbook to script to self-service to automatic, safely'],
 2, 12, [327, 325],
 [text(689, 1, 'What toil is',
   'Google’s SRE book defines toil as operational work that is manual, repetitive, automatable, tactical, without enduring value, and that grows as the service grows. Restarting a stuck job by hand every week, resizing disks on request or copying config between environments are toil. Designing a fix, writing a postmortem or attending a planning meeting are not toil, even if they feel like chores. The test is whether a machine could do it and whether it comes back.',
   ['toil']),
  text(689, 2, 'Misconception: all operations work is toil',
   'Responding to a novel incident needs judgement and teaches the team something, so it is not toil; responding to the same alert for the fiftieth time with the same steps is. Overhead such as meetings and reviews is not toil either. Measuring toil means logging repeatable, automatable tasks and their time. Google’s SRE teams aim to keep toil below 50% of each engineer’s time, so at least half goes into engineering that removes future toil.',
   ['toil']),
  diagram(689, 3, 'From runbook to automation', 'Each step removes a human from part of the loop.', ['automation-ladder'],
   ['A task is done by hand from memory', 'A runbook writes down the steps and the checks', 'A script runs the steps, started by a person', 'Self-service lets the requesting team run it with guardrails', 'Automation runs it on a trigger, with limits and logging', 'The underlying cause is fixed so the task is not needed']),
  text(689, 4, 'Worked example: is it worth automating?',
   'A manual task takes 15 minutes and happens 40 times a month: 15 × 40 = 600 minutes, or 10 hours a month. Automating it takes an estimated 30 hours, so it pays back in 30 ÷ 10 = 3 months, and keeps paying as the service grows. A task done twice a year for 10 minutes would never pay back 30 hours; a good runbook is enough for that one.',
   ['automation-payback']),
  text(689, 5, 'Trap: automation that hides the problem',
   'A service leaks memory, so someone automates a restart whenever memory is high. Pages stop, and the leak grows unnoticed until restarts happen every few minutes and a release makes it worse. Automatic fixes need limits, such as a maximum number of actions an hour, a log of every action and an alert when they run more often than expected. Automate the response, but keep fixing the cause.',
   ['runbooks', 'automation-ladder'])],
 [mc('t689-a1', 'toil', 'Which of these is toil?',
   [('a', 'Writing the postmortem for a new kind of outage'),
    ('b', 'Rotating the same credentials by hand every month'),
    ('c', 'Designing a migration plan for the main customer database'),
    ('d', 'Reviewing a teammate’s change to an alert rule')], 'b',
   'Manual, repetitive, automatable work that returns every month is toil. A postmortem for a new outage produces lasting learning, migration design is engineering, and reviewing changes is valuable overhead rather than toil.'),
  mc('t689-a2', 'automation-payback', 'Which task should a team automate first?',
   [('a', 'A 2-hour task done once a year, during the annual security audit'),
    ('b', 'A 5-minute task done twice a quarter by one person'),
    ('c', 'A 1-hour task done once, during a planned migration'),
    ('d', 'A 20-minute task done 30 times a month, growing with users')], 'd',
   'At about 10 hours a month and growing, the frequent task pays back fastest. The yearly task totals 2 hours a year, the twice-a-quarter one under an hour, and a one-off task has nothing to repeat, so a runbook is enough for each.'),
  mc('t689-a3', 'runbooks', 'What makes a runbook useful at 3 a.m.?',
   [('a', 'A history of how the system was designed and why'),
    ('b', 'Exact steps with checks, linked from the alert itself'),
    ('c', 'A complete list of the metrics and dashboards the service exposes'),
    ('d', 'The names of the engineers who built the service')], 'b',
   'Responders need concrete steps, how to verify each one, and to find the runbook from the page. Design history belongs in architecture docs, a full metric list is too much to scan, and names help only if those people are awake and still on the team.'),
  mc('t689-a4', 'automation-ladder', 'An auto-remediation restarts a service whenever memory is high. What safeguard matters most?',
   [('a', 'A cap on restarts per hour, with an alert when it is hit'),
    ('b', 'Running it only during working hours'),
    ('c', 'Restarting all instances together so the fix takes less time'),
    ('d', 'Hiding the restarts from dashboards to reduce noise')], 'a',
   'A rate limit stops runaway loops, and alerting when it triggers often makes the hidden cause visible. Working-hours-only defeats the purpose, restarting everything at once causes an outage, and hiding actions removes the evidence of a growing problem.'),
  est('t689-a5', 'automation-payback', 'A 15-minute manual task happens 40 times a month. Automating it takes about 30 hours. After how many months does the automation pay for itself?', 'months', 3,
   ['The task rate stays steady', 'Automation needs no upkeep'], '30 hours ÷ (15 min × 40 per month)', '15 × 40 = 600 minutes, 10 hours a month; 30 ÷ 10 = 3 months',
   'Sanity check: if the service doubles, so does the task count, and the payback halves, which is why toil that grows with the service is the first to automate.', 0.1, [30, 10]),
  order('t689-a6', 'automation-ladder', 'Order the usual path from manual task to no task.',
   ['Done by hand from memory', 'Written down as a runbook with checks', 'Scripted and started by a person', 'Run automatically on a trigger, with limits', 'Root cause fixed, so the task disappears'],
   ['s3', 's1', 's5', 's2', 's4'], 'Each step removes human effort; writing it down first makes the script correct, and fixing the cause is the final goal.')],
 flash(689, [('Toil?', 'Manual, repetitive, automatable, tactical work with no enduring value that grows with the service.'),
             ('Google SRE toil target?', 'Below 50% of each engineer’s time.'),
             ('Automation payback?', 'Build time ÷ hours saved per month.')]),
 src([('Google SRE book: Eliminating Toil', 'https://sre.google/sre-book/eliminating-toil/'),
      ('Google SRE workbook: Eliminating Toil', 'https://sre.google/workbook/eliminating-toil/'),
      ('Google SRE book: The Evolution of Automation at Google', 'https://sre.google/sre-book/automation-at-google/')]),
 deep(['toil', 'automation-payback', 'runbooks', 'automation-ladder'], 'How teams measure and remove toil',
  ['Toil is the operational work that scales with the service rather than with the team’s ideas: tasks that are manual, repetitive, automatable, tactical and leave nothing lasting behind. A little is unavoidable, but too much crowds out engineering, makes on-call miserable and causes mistakes, because people doing the same steps by hand eventually skip one. Google’s SRE teams set a goal of keeping toil below 50% of each engineer’s time.',
   'Measuring comes first. Teams log interrupts, tickets and on-call tasks for a few weeks, tagging each as toil or not, with its duration and frequency. The totals show where time goes and which few tasks make up most of it. Trends matter more than a single number: toil that grows with traffic or customers will take the whole team eventually unless removed.',
   'Prioritise by payback and risk. Time saved per month is the task duration times its frequency; payback is the build time divided by that. Tasks that are frequent, growing, error-prone or done under pressure at night go first. Rare tasks may only need a clear runbook. Include upkeep: a script nobody maintains becomes the next source of incidents.',
   'Automation is a ladder. A runbook captures the steps and checks, which also documents what a script must do. A script turns the runbook into one command. Self-service lets the team that needs the task run it, with guardrails, instead of filing a ticket. Full automation triggers on events, with rate limits, logging and an alert when it acts more than expected. The top rung is removing the need altogether by fixing the cause.',
   'Automation changes failure modes. Automatic actions can amplify a mistake across a whole fleet in seconds, so they need limits on scope and rate, a dry-run mode, and a clear way to stop them. They also hide symptoms, so their activity must be visible. Reviewing automation actions alongside pages keeps the team aware of what the system is doing on its behalf.'],
  ['Teams whose time goes to repeated tickets, manual deploys or the same pages each week.', 'Services that are growing, where manual work grows with them.'],
  ['Avoid automating a rare task where a runbook would do.', 'Avoid auto-remediation without rate limits, logging and an alert on repeated use.'],
  ['Rung', 'Human effort', 'Main risk'],
  [['Runbook', 'Full, but guided', 'Steps skipped under pressure'],
   ['Script or self-service', 'Starting it and checking', 'Script drifts from the system'],
   ['Automatic remediation', 'Review only', 'Hides causes or amplifies mistakes']],
  'Finding the toil worth removing',
  ['A team of 6 logs its work for a month', 'Each person works about 160 hours, illustrative', 'Logged toil totals 400 hours'],
  ['Team hours: 6 × 160 = 960 hours.',
   'Toil share: 400 ÷ 960 ≈ 42%, under the 50% cap but close to it.',
   'If the top three tasks are 250 of those hours, automating them alone brings toil to about 150 ÷ 960 ≈ 16%.'],
  'A month of logging shows that a few repeated tasks make up most of the toil, so automating three of them frees about a quarter of the team’s time.',
  'Toil in Google’s SRE books', 'Publicly reported',
  'Google’s SRE book defines toil as work tied to running a production service that tends to be manual, repetitive, automatable, tactical, devoid of enduring value, and that scales linearly as a service grows. It describes an advertised goal of keeping toil below 50% of each SRE’s time. The SRE workbook gives practical steps to measure, prioritise and eliminate toil, and its automation chapter describes moving from manual work to fully automatic systems.',
  [('“Ops work is all toil, so let’s automate everything.”', '“I’d log the repeated tasks, then automate the frequent ones with the best payback.”'),
   ('“Pages stopped since we auto-restart it.”', '“I’d cap the restarts, alert when they rise, and fix the leak behind them.”')],
  ['Toil is manual, repetitive, automatable work that grows with the service.', 'Measure it, and keep it below about half of the team’s time.', 'Automate by payback: build time ÷ hours saved per month.', 'Climb from runbook to script to self-service to automation, with limits.']),
 predict('The helpful restart',
  'An automation restarts any instance whose memory passes 90%, with no limit and no alert. It runs about twice a day at first. A new release doubles the leak rate.',
  [('a', 'Restarts become frequent and capacity drops, unnoticed until users see errors',
    'Right: restarts hide the leak, so the first visible signal is user impact.'),
   ('b', 'The automation pages on-call once restarts become frequent',
    'It was built with no alert, so nothing tells anyone it is busy.'),
   ('c', 'Memory stops leaking, because restarts reclaim it each time',
    'Restarts free the memory but leave the leak in the code, so it grows back.')], 'a',
  'Give remediations a rate limit, alert when it is reached, and keep a ticket open for the cause.'),
 see([(327, 'Incidents and postmortems that reveal repeated manual work'), (690, 'Alert reviews that find pages worth automating'), (325, 'Infrastructure as code, which removes many manual changes')])))
